// Supplemental design calculator. No network, account storage, payments or original game data.
import fs from 'node:fs';
export const config=JSON.parse(fs.readFileSync(new URL('./growth-config.json',import.meta.url),'utf8'));
const int=(v,min=0,max=Number.MAX_SAFE_INTEGER)=>{if(!Number.isSafeInteger(v)||v<min||v>max)throw Error('INVALID');return v;};
export function cumulative(kind,level){const c=config.curves[kind];if(!c)throw Error('INVALID');int(level,1,c.maxLevel);return c.coefficient*level*(level-1)/2;}
export function advance(kind,level,xp,amount,cap=config.curves[kind]?.maxLevel){const c=config.curves[kind];if(!c)throw Error('INVALID');int(cap,1,c.maxLevel);int(level,1,cap);int(xp,0,level===cap?0:c.coefficient*level-1);int(amount,1,1000000);const need=cumulative(kind,cap)-cumulative(kind,level)-xp;const spent=Math.min(amount,need);let rest=xp+spent;while(level<cap&&rest>=c.coefficient*level){rest-=c.coefficient*level;level++;}return {level,xp:rest,spent,unused:amount-spent};}
export function quoteHeroUpgrade({kind='hero',level,xp,star,amount,bank,coins}){if(!['hero','fodder'].includes(kind)||!config.starCaps[star])throw Error('INVALID');int(bank,0,config.bankCapacity);int(coins);const result=advance(kind,level,xp,amount,config.starCaps[star]);if(!result.spent)throw Error('CAPPED');const cost=Math.ceil(result.spent/config.heroXpCoinsDivisor);if(bank<result.spent||coins<cost)throw Error('INSUFFICIENT');return {...result,coinCost:cost,bankAfter:bank-result.spent,coinsAfter:coins-cost};}
export function quoteStar(target,materials,coins){int(coins);const r=config.starRecipes[target.star];if(!r||target.level!==config.starCaps[target.star]||target.xp!==0)throw Error('NOT_READY');if(materials.length!==r.count||new Set(materials.map(m=>m.id)).size!==r.count)throw Error('INVALID');for(const m of materials){if(!m.id||m.id===target.id||m.star!==target.star||m.locked||m.assigned||m.referenced||m.dispatched)throw Error('PROTECTED_OR_INVALID');}if(coins<r.coins)throw Error('INSUFFICIENT');return {star:target.star+1,level:target.level,xp:0,coinCost:r.coins,coinsAfter:coins-r.coins,consumedIds:materials.map(m=>m.id)};}
export function quoteAwaken(recipe,inventory,already=false){const r=config.awakeningRecipes[recipe];if(!r||already)throw Error('NOT_APPLICABLE');const after={...inventory};for(const [key,n] of Object.entries(r)){int(after[key]??0);if((after[key]??0)<n)throw Error('INSUFFICIENT');after[key]-=n;}return {after,cost:{...r},awakened:true};}
export function skillChoice(levels,draw){if(!Array.isArray(levels)||!levels.length)throw Error('INVALID');levels.forEach(l=>int(l,1,config.skillMaxLevel));const eligible=levels.flatMap((l,i)=>l<config.skillMaxLevel?[i]:[]);if(!eligible.length)throw Error('CAPPED');if(typeof draw!=='number'||!Number.isFinite(draw)||draw<0||draw>=1)throw Error('INVALID');const selected=eligible[Math.floor(draw*eligible.length)],after=[...levels];after[selected]++;return {selected,after};}
export function quoteGuardian(level,xp,amount,accountLevel,bank){int(accountLevel,1,60);int(bank,0,config.bankCapacity);const result=advance('guardian',level,xp,amount,Math.min(40,accountLevel));if(!result.spent)throw Error('CAPPED');if(bank<result.spent)throw Error('INSUFFICIENT');return {...result,bankAfter:bank-result.spent,milestones:config.guardianMilestones.filter(n=>n>level&&n<=result.level)};}
export function deposit(bank,unitXp,count){int(bank,0,config.bankCapacity);int(unitXp,1,1000000);int(count,1,1000);const after=bank+unitXp*count;if(after>config.bankCapacity)throw Error('CAPACITY');return after;}
export function mainAttributes(account,guardian){int(account,1,60);int(guardian,1,Math.min(account,40));return {attack:100+10*(account-1)+5*(guardian-1),hp:1000+100*(account-1)+50*(guardian-1),defense:50+5*(account-1)+2*(guardian-1),speed:100+Math.floor((guardian-1)/5)};}
export function heroAttributes(template,level,star,awakened=false){const t=config.heroTemplates[template];if(!t||!config.starCaps[star]||(awakened&&!t.awakening))throw Error('INVALID');int(level,1,config.starCaps[star]);const result={};for(const key of ['attack','hp','defense']){const base=t.base[key]+t.growth[key]*(level-1);result[key]=Math.floor(base*config.starMultipliersBp[star]*(awakened?11000:10000)/100000000);}result.speed=t.base.speed+(awakened?5:0);return result;}
export function transfer(a,b,tickets){int(tickets);if(!tickets)throw Error('INSUFFICIENT');if(!a.id||a.id===b.id||a.curve!==b.curve||a.busy||b.busy||a.assigned||b.assigned||a.referenced||b.referenced||a.dispatched||b.dispatched)throw Error('INVALID');for(const x of [a,b]){if(!config.starCaps[x.star]||!['hero','fodder'].includes(x.curve))throw Error('INVALID');advance(x.curve,x.level,x.xp,1,config.starCaps[x.star]);}const form=x=>({star:x.star,level:x.level,xp:x.xp});return {a:{...a,...form(b)},b:{...b,...form(a)},tickets:tickets-1};}
